             tpd_B_Y : VitalDelayType01 := (0.0135536 ns, 0.013541 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
