                    MsgSeverity    => WARNING );

                VitalRecoveryRemovalCheck (
                    TestSignal     => SN_dly,
                    TestSignalName => "SN",
                    RefSignal      => GN_dly,
                    RefSignalName  => "GN",
                    Recovery       => trecovery_SN_GN_posedge_posedge,
